const title=(l)=>{const m=l.match(/^\s+it\((['"`])(.*)\1,/);return m&&m[2]};
const oldL=fs.readFileSync('/tmp/old.ts','utf8').split('\n');
const newL=fs.readFileSync('src/transport/sessionResume.test.ts','utf8').split('\n');
const nl={};newL.forEach((l,i)=>{const t=title(l);if(t)nl[t]=i+1});
for(const f of ['specs/hal-engine-session-resume/spec.md','specs/hal-engine-websocket-protocol/spec.md']){
 let s=fs.readFileSync(f,'utf8');
 s=s.replace(/sessionResume\.test\.ts#L(\d+)/g,(m,n)=>{const t=title(oldL[n-1]);if(!t||!nl[t]){console.log('unmapped',f,n);return m}return 'sessionResume.test.ts#L'+nl[t]});
 fs.writeFileSync(f,s);
}
EOF
